struct Widget {
    int v;
    Widget(int x) : v(x) {}
};

Widget* w = new Widget(3);
// 1. operator new(sizeof(Widget))
// 2. Widget(3) runs in that memory
// 3. typed address goes into w

// What  new Widget(3)  does:
void* raw = ::operator new(sizeof(Widget));  // allocate only
Widget* w = new (raw) Widget(3);             // construct only

// What  delete w  does:
w->~Widget();                                // destroy
::operator delete(raw);                      // deallocate

struct Bad {
    Bad() { throw std::runtime_error("boom"); }
};

try {
    Bad* b = new Bad;     // memory is freed for you
} catch (const std::exception&) {}

std::size_t n = 1ULL << 50;   // petabytes of ints
